#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
uniform float2 amzVelocity,amzPivot,amzScale;
uniform float amzAngularVelocity,amzScaleVelocity,amzStartTime,amzEndTime;

struct AC_ImageInfo { int texture; float2 amzLocal_size; };
const float3x3 labPlaneInverse=float3x3(1);
float4x4 amzQuaternion(float4 q) {
    q /= max(length(q),0.000001);
    float x=q.x,y=q.y,z=q.z,w=q.w;
    return float4x4(1-2*(y*y+z*z),2*(x*y+w*z),2*(x*z-w*y),0,
                    2*(x*y-w*z),1-2*(x*x+z*z),2*(y*z+w*x),0,
                    2*(x*z+w*y),2*(y*z-w*x),1-2*(x*x+y*y),0,0,0,0,1);
}
const int amzPass=1;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
uniform shader amzt_blurBuf;
float4 amzSample_blurBuf(float2 uv) { return float4(amzt_blurBuf.eval(((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0))); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);if(tex==1) return amzSample_blurBuf(uv);return float4(0.0); }
float4 amzTexture(int tex,float2 uv,float bias){return amzTexture(tex,uv);}
uniform float2 amzp_sourcePoint;
uniform float amzp_rotation;
uniform float amzp_emitRadius;
uniform float amzp_force;
uniform float amzp_intensity;
uniform float amzp_spread;
uniform float amzp_speed;
uniform float amzp_gravity;
uniform float amzp_buoyancy;
uniform float amzp_vorticity;
uniform float amzp_viscosity;
uniform float amzp_swirl;
uniform float amzp_turbAmount;
uniform float amzp_turbSize;
uniform float amzp_turbSpeed;
uniform float amzp_tailLength;
uniform float amzp_evolution;
uniform float amzp_shading;
uniform float amzp_bloomIntensity;
uniform float amzp_bloomThreshold;
uniform float amzp_colorMode;
layout(color) uniform half4 amzp_colorA;
layout(color) uniform half4 amzp_colorB;
uniform float amzp_colorMix;
uniform float amzp_blendMode;
uniform float amzp_opacity;
uniform float amzp_blend;



        float hash(float2 p) {
            return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
        }

        float noise(float2 p) {
            float2 i = floor(p);
            float2 f = fract(p);
            f = f * f * (3.0 - 2.0 * f);
            return mix(mix(hash(i), hash(i + float2(1,0)), f.x),
                       mix(hash(i + float2(0,1)), hash(i + float2(1,1)), f.x), f.y);
        }

        float fbm(float2 p, float amzLocal_time) {
            float v = 0.0;
            float a = 0.5;
            float2x2 rot = float2x2(cos(0.5), sin(0.5), -sin(0.5), cos(0.5));
            for (int i = 0; i < 4; i++) {
                v += a * noise(p + amzLocal_time);
                p = rot * p * 2.1;
                a *= 0.5;
            }
            return v;
        }

        void amzRender() {
            float2 uv = amzScreenNorm();
            float aspect = screen.zw.x / screen.zw.y;
            float2 p = uv; p.x *= aspect;

            float t = time * (amzp_speed / 100.0) + amzp_evolution;
            float2 emit = (amzp_sourcePoint / 500.0) + float2(0.5 * aspect, 0.5);


            float eps = 0.05;
            float2 nUV = p * (100.0 / max(amzp_turbSize, 1.0));
            float n1 = fbm(nUV, t * (amzp_turbSpeed / 100.0) * 0.1);


            float dist = distance(p, emit);
            float emitMask = smoothstep(amzp_emitRadius / 100.0, 0.0, dist);
            float rad = radians(amzp_rotation);
            float2 dirVec = float2(cos(rad), sin(rad));
            float2 emitDir = dirVec * (amzp_force / 100.0) * emitMask;


            float dndx = (fbm(nUV + float2(eps, 0.0), t * 0.1) - n1) / eps;
            float dndy = (fbm(nUV + float2(0.0, eps), t * 0.1) - n1) / eps;
            float2 curlDir = float2(dndy, -dndx) * (amzp_vorticity / 10.0) * (amzp_turbAmount / 100.0);


            float2 gForce = float2(0.0, (amzp_gravity / 100.0) + (amzp_buoyancy / 100.0));


            float2 flow = (emitDir + curlDir + gForce) * (amzp_intensity / 100.0);



            float visFactor = mix(1.0, 0.05, amzp_viscosity / 100.0);
            float2 flowOffset = flow * visFactor;


            if(amzp_swirl > 0.0) {
                float sRad = radians(amzp_swirl * 3.6);
                float2x2 sRot = float2x2(cos(sRad * n1), sin(sRad * n1), -sin(sRad * n1), cos(sRad * n1));
                flowOffset *= sRot;
            }

            float2 sampleUV = uv - flowOffset;


            float4 src = amzTexture(0, uv);
            float4 fluid = amzTexture(0, clamp(sampleUV, 0.0, 1.0));


            float3 finalRgb = fluid.rgb;
            if(int(amzp_colorMode) == 1) {
                float mixVal = clamp(length(flow) * 10.0 + (amzp_colorMix / 360.0), 0.0, 1.0);
                float3 tint = mix(amzp_colorA.rgb, amzp_colorB.rgb, mixVal);
                finalRgb = mix(finalRgb, tint, length(flow) * 2.0);
            }


            if(amzp_shading > 0.0) {
                float4 blur = amzTexture(1, sampleUV);
                float shadow = smoothstep(0.5, 0.0, blur.a - fluid.a);
                finalRgb *= mix(1.0, 1.0 - shadow, amzp_shading / 100.0);
            }

            if(amzp_bloomIntensity > 0.0) {
                float lum = dot(finalRgb, float3(0.299, 0.587, 0.114));
                float bloom = smoothstep(amzp_bloomThreshold / 100.0, 1.0, lum);
                finalRgb += finalRgb * bloom * (amzp_bloomIntensity / 100.0) * 2.0;
            }


            float3 result;
            if(int(amzp_blendMode) == 1) result = src.rgb + finalRgb;
            else if(int(amzp_blendMode) == 2) result = 1.0 - (1.0 - src.rgb) * (1.0 - finalRgb);
            else result = mix(src.rgb, finalRgb, fluid.a);

            float finalAlpha = fluid.a * (amzp_opacity / 100.0);
            float3 finalOutput = mix(src.rgb, result, amzp_blend);

            amzOutput = float4(clamp(finalOutput, 0.0, 4.0), max(src.a, finalAlpha));
        }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }

